export const MANSION_LOT_DATA_URI = "data:image/jpeg;base64,";
export const MANSION_LOT_WIDTH = 500;
export const MANSION_LOT_HEIGHT = 629;

// North-row lot (the housing frame's top-left slot) — native y=0 is the
// mansion itself (far from the road), native y=HEIGHT is past the gate,
// near the road. See drawGroundImageLot's dir="up" branch: the photo is
// mirrored about the lot's near-road edge instead of being re-cropped, so
// this orientation (unlike every south-row lot so far) matches how the
// source photo was received — gate near the bottom.
//
// The original photo (751 tall at this width) was too tall to fit the
// space above the road without the mansion's own roofline being clipped
// off the top of the screen — trimmed by removing a 200px band of the
// long straight driveway between the entrance courtyard and the main
// fountain (the two flanking gardens are pure repeated path/hedge there,
// nothing lost by shortening it) down to 551px, then padded by 78px past
// the gate (a flat repeat of its own last few rows) so the north
// sidewalk's hidden zone (~75px at this scale) eats only that padding
// instead of the real gate/fence, which stays fully visible right at the
// sidewalk.
//
// No clean full-width grass band to repeat-tile downward (trees and
// hedges run along both edges almost everywhere) — leftover depth on a
// screen tall enough to exceed the photo's own height falls back to a
// flat lawn-green fill instead (see groundFallbackColor).
export const MANSION_LOT_GROUND_STRIP_TOP = 0;
export const MANSION_LOT_GROUND_STRIP_HEIGHT = 1;
